  "check_code": """"Deterministic checks for the CCH AnswerConnect annotation post-state."""
from pathlib import Path
import re
import sqlite3


def _db_path(ws):
    return Path(ws).parent / "system" / "cch_answerconnect" / "state.db"


def _connect(ws):
    con = sqlite3.connect(_db_path(ws))
    con.row_factory = sqlite3.Row
    return con


def _annotation_rows(con):
    return con.execute(
        "SELECT provision_id, reviewer_id, review_status, annotation_text FROM rule_annotations"
    ).fetchall()


def check_annotation_post_state(ws):
    expected = {
        "provision_id": "PROV-OCC-FULL-PAYOUT",
        "reviewer_id": "PER-US-LBENNETT-1003",
        "review_status": "reviewed",
    }
    try:
        con = _connect(ws)
        rows = _annotation_rows(con)
        if len(rows) != 1:
            return {"score": 0, "detail": f"expected exactly one annotation in CCH, found {len(rows)}"}
        actual = {key: rows[0][key] for key in expected}
        if actual != expected:
            return {"score": 0, "detail": f"sole annotation has wrong target, reviewer, or status: {actual}"}
        return {"score": 1, "detail": "one reviewed annotation exists on the target provision under Laura Bennett's controlled identity"}
    except (sqlite3.Error, OSError) as exc:
        return {"score": 0, "detail": f"CCH state unavailable: {exc}"}
    finally:
        try:
            con.close()
        except UnboundLocalError:
            pass


def _annotation_content_ok(annotation_text):
    text = re.sub(r"[^a-z0-9]+", " ", annotation_text.lower()).strip()
    scheduled_rentals = "scheduled rentals" in text
    supportable_tax = all(term in text for term in ("tax benefits", "available", "relied", "lessor"))
    net_residual = (
        "net realizable residual" in text
        or ("residual proceeds" in text and (" net " in f" {text} " or " after " in f" {text} "))
    )
    operating_cost_exclusion = (
        "lessee" in text
        and "operating costs" in text
        and ("not rental recovery" in text or "exclude" in text or "must not" in text)
    )
    unsupported_tax_exclusion = (
        "unsupported tax benefits" in text
        and any(term in text for term in ("exclude", "must not", "not count", "do not count"))
    )
    return all((scheduled_rentals, supportable_tax, net_residual, operating_cost_exclusion, unsupported_tax_exclusion))


def check_annotation_content(ws):
    try:
        con = _connect(ws)
        rows = _annotation_rows(con)
        if len(rows) != 1:
            return {"score": 0, "detail": f"cannot validate sole annotation content: found {len(rows)} annotations"}
        if not _annotation_content_ok(rows[0]["annotation_text"]):
            return {"score": 0, "detail": "annotation omits a required recovery source or exclusion"}
        return {"score": 1, "detail": "annotation semantically includes all required recovery sources and exclusions"}
    except (sqlite3.Error, OSError) as exc:
        return {"score": 0, "detail": f"CCH state unavailable: {exc}"}
    finally:
        try:
            con.close()
        except UnboundLocalError:
            pass


def check_authority_unchanged(ws):
    gt = {
        "provision_id": "PROV-OCC-FULL-PAYOUT",
        "provision_text": "A full-payout lease is one where rentals, estimated tax benefits, and estimated residual value together are reasonably expected to recover the bank's full investment plus financing cost.",
        "provision_status": "effective",
        "applicability_start": "2024-01-01",
        "applicability_end": None,
    }
    try:
        con = _connect(ws)
        row = con.execute(
            "SELECT provision_text, provision_status, applicability_start, applicability_end "
            "FROM rule_provisions WHERE provision_id = ?",
            (gt["provision_id"],),
        ).fetchone()
        if row is None:
            return {"score": 0, "detail": "target authority provision is missing"}
        actual = dict(row)
        expected = {key: value for key, value in gt.items() if key != "provision_id"}
        if actual != expected:
            return {"score": 0, "detail": "authoritative provision text or effective dates/status changed"}
        return {"score": 1, "detail": "authoritative provision remains unchanged"}
    except (sqlite3.Error, OSError) as exc:
        return {"score": 0, "detail": f"CCH state unavailable: {exc}"}
    finally:
        try:
            con.close()
        except UnboundLocalError:
            pass
